<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Modules\B2B\Application\B2BApprovalService; use App\Modules\B2B\Application\B2BWorkflowService; use App\Modules\B2B\Application\B2BEnterpriseService; use App\Modules\B2B\Application\B2BQuoteService; use App\Modules\B2B\Application\B2BCommercialService; use App\Modules\B2B\Application\B2BPurchaseOrderService; use App\Support\Arr;
use Siro\Core\Controller; use Siro\Core\Request; use Siro\Core\Response;
final class B2BController extends Controller {
  public function __construct(private readonly B2BApprovalService $service, private readonly B2BWorkflowService $workflow, private readonly B2BEnterpriseService $enterprise, private readonly B2BQuoteService $quotes, private readonly B2BCommercialService $commercial, private readonly B2BPurchaseOrderService $purchaseOrders) {}
  public function createGroup(Request $request): Response { try { return $this->created($this->commercial->createGroup(Arr::requiredParam($request,'id'),$request->validate(['code'=>'required|string','name'=>'required|string'])),'Group created'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
  public function rolePolicy(Request $request): Response { try { return $this->created($this->commercial->setRolePolicy(Arr::requiredParam($request,'id'),Arr::requiredParam($request,'role'),$request->validate(['policy'=>'nullable','approval_limit_minor'=>'nullable|integer'])),'Role policy saved'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
  public function priceList(Request $request): Response { try { return $this->created($this->commercial->createPriceList(Arr::requiredParam($request,'id'),$request->validate(['code'=>'required|string','currency'=>'nullable|string'])),'Price list created'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
  public function priceTier(Request $request): Response { try { return $this->created($this->commercial->addPriceTier(Arr::requiredParam($request,'id'),$request->validate(['variant_id'=>'required|string','minimum_qty'=>'required|integer','unit_price_minor'=>'required|integer'])),'Price tier saved'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
  public function terms(Request $request): Response { try { return $this->created($this->commercial->setTerms(Arr::requiredParam($request,'id'),$request->validate(['minimum_order_minor'=>'nullable|integer','minimum_order_qty'=>'nullable|integer','credit_limit_minor'=>'nullable|integer','payment_terms_days'=>'nullable|integer','currency'=>'nullable|string'])),'Commercial terms saved'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
  public function validateBulk(Request $request): Response { $u=$request->user(); $uid=is_array($u)?Arr::int($u,'id'):0; $data=$request->validate(['lines'=>'required|array']); $lines=[]; if(is_array($data['lines']??null)) foreach($data['lines'] as $line) if(is_array($line)) { $clean=[]; foreach($line as $field=>$value) if(is_string($field)) $clean[$field]=$value; $lines[]=$clean; } try { return $this->success($this->commercial->validateBulk(Arr::requiredParam($request,'id'),$uid,$lines,(string)$request->header('Idempotency-Key','')),'Bulk order validation'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),$e->getMessage()==='User is not a company member'?403:422); } }
  public function createCatalog(Request $request): Response { try { return $this->created($this->enterprise->createCatalog(Arr::requiredParam($request,'id'),$request->validate(['code'=>'required|string','name'=>'required|string','currency'=>'nullable|string','scope'=>'nullable|string'])),'Catalog created'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
  public function addCatalogItem(Request $request): Response { $d=$request->validate(['variant_id'=>'required|string','minimum_qty'=>'nullable|integer']); try { return $this->created($this->enterprise->addCatalogItem(Arr::requiredParam($request,'id'),Arr::requiredParam($request,'catalog'),Arr::requiredStr($d,'variant_id'),Arr::int($d,'minimum_qty',1)),'Catalog item added'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
  public function negotiatedPrice(Request $request): Response { try { return $this->created($this->enterprise->setNegotiatedPrice(Arr::requiredParam($request,'id'),$request->validate(['variant_id'=>'required|string','currency'=>'nullable|string','unit_price_minor'=>'required|integer','minimum_qty'=>'nullable|integer'])),'Negotiated price saved'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
  public function quote(Request $request): Response { $u=$request->user(); $uid=is_array($u)?Arr::int($u,'id'):0; $company=Arr::requiredParam($request,'id'); $d=$request->validate(['currency'=>'required|string','lines'=>'required|array','expires_at'=>'nullable|string','purchase_order_number'=>'nullable|string','payment_terms_days'=>'nullable|integer']); /** @var array<int,array<string,mixed>> $lines */ $lines=[]; if (is_array($d['lines']??null)) foreach ($d['lines'] as $line) if (is_array($line)) { $clean=[]; foreach ($line as $key=>$value) if (is_string($key)) $clean[$key]=$value; $lines[]=$clean; } $header=$request->header('Idempotency-Key',''); $key=is_string($header)?$header:''; try { return $this->created($this->quotes->create($company,$uid,Arr::requiredStr($d,'currency'),$lines,$key,is_string($d['expires_at']??null)?$d['expires_at']:null,is_string($d['purchase_order_number']??null)?$d['purchase_order_number']:null,Arr::int($d,'payment_terms_days',0)),'Quote created'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
  public function quoteTransition(Request $request): Response { $u=$request->user(); $uid=is_array($u)?Arr::int($u,'id'):0; $action=Arr::requiredParam($request,'action'); $key=$request->header('Idempotency-Key',''); $reason=$request->input('reason',''); try { return $this->success($this->quotes->transition(Arr::requiredParam($request,'id'),$uid,$action,is_string($key)?$key:'',is_string($reason)?$reason:''),'Quote transitioned'); } catch (\RuntimeException $e) { $status = match ($e->getMessage()) { 'B2B quote not found' => 404, 'User is not a company member', 'User cannot approve for this company', 'Approval scope is not granted' => 403, default => 422 }; return $this->error($e->getMessage(),$status); } }
   public function quoteShow(Request $request): Response { $u=$request->user(); $uid=is_array($u)?Arr::int($u,'id'):0; try { return $this->success($this->quotes->show(Arr::requiredParam($request,'id'),$uid),'Quote'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),404); } }
  public function quoteConvert(Request $request): Response { $u=$request->user(); $uid=is_array($u)?Arr::int($u,'id'):0; try { return $this->success($this->quotes->convert(Arr::requiredParam($request,'id'),$uid,(string)$request->header('Idempotency-Key','')),'Quote converted'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),$e->getMessage()==='B2B quote not found'?404:422); } }
 public function createCompany(Request $request): Response { $data=$request->validate(['name'=>'required|string','status'=>'nullable|string']); return $this->created($this->service->createCompany($data),'Company created'); }
  public function addMember(Request $request): Response { $data=$request->validate(['user_id'=>'required|integer','role'=>'required|string']); try { return $this->created($this->service->addMember(Arr::requiredParam($request,'id'),Arr::requiredInt($data,'user_id'),Arr::requiredStr($data,'role')),'Member added'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
 public function addScope(Request $request): Response { $data=$request->validate(['scope'=>'required|string','channel_id'=>'nullable|string','approval_limit_minor'=>'nullable|integer']); return $this->created($this->service->addScope(Arr::requiredParam($request,'id'),$data),'Approval scope added'); }
 public function approve(Request $request): Response { $user=$request->user(); $userId=is_array($user)?Arr::int($user,'id'):0; try { $result=$this->service->approve(Arr::requiredParam($request,'id'),$userId,(string)$request->header('Idempotency-Key','')); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),$e->getMessage()==='B2B order not found'?404:403); } return $this->success($result,'Order approved'); }
 public function createCreditAccount(Request $request): Response { $data=$request->validate(['limit_minor'=>'required|integer','currency'=>'nullable|string','payment_terms_days'=>'nullable|integer']); try { return $this->created($this->service->createCreditAccount(Arr::requiredParam($request,'id'),$data),'Credit account created'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
  public function credit(Request $request): Response { $user=$request->user(); $userId=is_array($user)?Arr::int($user,'id'):0; $platformAdmin=is_array($user)&&in_array($user['role']??null,['admin','owner'],true); try { return $this->success($this->workflow->credit(Arr::requiredParam($request,'id'),$userId,$platformAdmin),'Credit evidence'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),$e->getMessage()==='User is not a company member'?403:404); } }
 public function transition(Request $request): Response { $user=$request->user(); $userId=is_array($user)?Arr::int($user,'id'):0; $data=$request->validate(['state'=>'required|string','reason'=>'nullable|string']); $header=$request->header('Idempotency-Key',''); $key=is_string($header)?$header:''; try { $result=$this->workflow->transition(Arr::requiredParam($request,'id'),$userId,Arr::requiredStr($data,'state'),$key,isset($data['reason'])&&is_string($data['reason'])?$data['reason']:null); return $this->success($result,'B2B order transitioned'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),in_array($e->getMessage(),['B2B order not found'],true)?404:422); } }
 public function draft(Request $request): Response { return $this->transitionTo($request, 'draft'); }
 public function submit(Request $request): Response { return $this->transitionTo($request, 'submit'); }
 public function approveForCompany(Request $request): Response { return $this->transitionTo($request, 'approve'); }
 public function reject(Request $request): Response { return $this->transitionTo($request, 'reject'); }
 private function transitionTo(Request $request, string $state): Response { $user=$request->user(); $userId=is_array($user)?Arr::int($user,'id'):0; $input=$request->input('reason',''); $reason=is_string($input)?$input:''; try { return $this->success($this->workflow->transition(Arr::requiredParam($request,'id'),$userId,$state,(string)$request->header('Idempotency-Key',''),$reason),'B2B order transitioned'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),$e->getMessage()==='B2B order not found'?404:422); } }
 public function createContract(Request $request): Response { $data=$request->validate(['contract_number'=>'required|string','credit_limit_minor'=>'nullable|integer','currency'=>'nullable|string','starts_at'=>'nullable|string','ends_at'=>'nullable|string']); try { return $this->created($this->service->createContract(Arr::requiredParam($request,'id'),$data),'Contract created'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
  public function approveContract(Request $request): Response { $user=$request->user(); $userId=is_array($user)?Arr::int($user,'id'):0; try { $result=$this->service->approveContract(Arr::requiredParam($request,'id'),$userId,(string)$request->header('Idempotency-Key','')); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),$e->getMessage()==='B2B contract not found'?404:403); } return $this->success($result,'Contract approved'); }
  public function createPurchaseOrder(Request $request): Response { $user=$request->user(); $userId=is_array($user)?Arr::int($user,'id'):0; try { return $this->created($this->purchaseOrders->create(Arr::requiredParam($request,'id'),$userId,$request->validate(['po_number'=>'required|string','currency'=>'nullable|string','total_minor'=>'required|integer','contract_id'=>'nullable|string']),(string)$request->header('Idempotency-Key','')),'Purchase order created'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
  public function purchaseOrderTransition(Request $request): Response { $user=$request->user(); $userId=is_array($user)?Arr::int($user,'id'):0; $input=$request->input('reason',''); try { return $this->success($this->purchaseOrders->transition(Arr::requiredParam($request,'id'),$userId,Arr::requiredParam($request,'action'),(string)$request->header('Idempotency-Key',''),is_string($input)?$input:''),'Purchase order transitioned'); } catch (\RuntimeException $e) { return $this->error($e->getMessage(),422); } }
}
